class Solution {
    int dist[16][16];
    int memo[16][1 << 15][2];
    int p;

    int minimax(int u, int mask, int is_alice) {
        if (mask == (1 << p) - 1) return 0;
        if (memo[u][mask][is_alice] != -1) return memo[u][mask][is_alice];

        if (is_alice) {
            int best = 0;
            for (int nxt = 0; nxt < p; ++nxt) {
                if (!(mask & (1 << nxt))) {
                    int d = dist[u][nxt + 1];
                    best = std::max(best, d + minimax(nxt + 1, mask | (1 << nxt), 0));
                }
            }
            return memo[u][mask][is_alice] = best;
        } else {
            int best = 1e9;
            for (int nxt = 0; nxt < p; ++nxt) {
                if (!(mask & (1 << nxt))) {
                    int d = dist[u][nxt + 1];
                    best = std::min(best, d + minimax(nxt + 1, mask | (1 << nxt), 1));
                }
            }
            return memo[u][mask][is_alice] = best;
        }
    }

