import java.util.*;

class Solution {
    private int[][] dist = new int[16][16];
    private int[][][] memo;
    private int p;

    public int maxMoves(int kx, int ky, int[][] positions) {
        p = positions.length;
        List<int[]> pts = new ArrayList<>();
        pts.add(new int[]{kx, ky});
        for (int[] pos : positions) pts.add(pos);

        int[][] moves = {{-2, -1}, {-2, 1}, {-1, -2}, {-1, 2}, {1, -2}, {1, 2}, {2, -1}, {2, 1}};
        for (int i = 0; i <= p; i++) {
            int[][] dGrid = new int[50][50];
            for (int[] row : dGrid) Arrays.fill(row, -1);
            Queue<int[]> q = new LinkedList<>();
            int[] start = pts.get(i);
            dGrid[start[0]][start[1]] = 0;
            q.offer(start);

            while (!q.isEmpty()) {
                int[] curr = q.poll();
                int x = curr[0], y = curr[1];
                for (int[] m : moves) {
                    int nx = x + m[0], ny = y + m[1];
                    if (nx >= 0 && nx < 50 && ny >= 0 && ny < 50 && dGrid[nx][ny] == -1) {
                        dGrid[nx][ny] = dGrid[x][y] + 1;
                        q.offer(new int[]{nx, ny});
                    }
                }
            }

            for (int j = 0; j <= p; j++) {
                int[] target = pts.get(j);
                dist[i][j] = dGrid[target[0]][target[1]];
            }
        }

        memo = new int[16][1 << p][2];
        for (int[][] m1 : memo) {
            for (int[] m2 : m1) Arrays.fill(m2, -1);
        }

        return minimax(0, 0, 1);
    }

    private int minimax(int u, int mask, int isAlice) {
        if (mask == (1 << p) - 1) return 0;
        if (memo[u][mask][isAlice] != -1) return memo[u][mask][isAlice];

        if (isAlice == 1) {
            int best = 0;
            for (int nxt = 0; nxt < p; nxt++) {
                if ((mask & (1 << nxt)) == 0) {
                    int d = dist[u][nxt + 1];
                    best = Math.max(best, d + minimax(nxt + 1, mask | (1 << nxt), 0));
                }
            }
            return memo[u][mask][isAlice] = best;
        } else {
            int best = Integer.MAX_VALUE;
            for (int nxt = 0; nxt < p; nxt++) {
                if ((mask & (1 << nxt)) == 0) {
                    int d = dist[u][nxt + 1];
                    best = Math.min(best, d + minimax(nxt + 1, mask | (1 << nxt), 1));
                }
            }
            return memo[u][mask][isAlice] = best;
        }
    }
}

var maxMoves = function(kx, ky, positions) {
    const p = positions.length;
    const pts = [[kx, ky], ...positions];
    const dist = Array.from({ length: p + 1 }, () => new Int32Array(p + 1));
    const moves = [[-2, -1], [-2, 1], [-1, -2], [-1, 2], [1, -2], [1, 2], [2, -1], [2, 1]];

    for (let i = 0; i <= p; i++) {
        const dGrid = Array.from({ length: 50 }, () => new Int32Array(50).fill(-1));
        const [sx, sy] = pts[i];
        dGrid[sx][sy] = 0;
        const q = [[sx, sy]];
        let head = 0;

        while (head < q.length) {
            const [x, y] = q[head++];
            const curDist = dGrid[x][y];
            for (let m = 0; m < 8; m++) {
                const nx = x + moves[m][0], ny = y + moves[m][1];
                if (nx >= 0 && nx < 50 && ny >= 0 && ny < 50 && dGrid[nx][ny] === -1) {
                    dGrid[nx][ny] = curDist + 1;
                    q.push([nx, ny]);
                }
            }
        }

        for (let j = 0; j <= p; j++) {
            const [tx, ty] = pts[j];
            dist[i][j] = dGrid[tx][ty];
        }
    }

    const memo = Array.from({ length: p + 1 }, () => 
        Array.from({ length: 1 << p }, () => new Int32Array(2).fill(-1))
    );

    function minimax(u, mask, isAlice) {
        if (mask === (1 << p) - 1) return 0;
        if (memo[u][mask][isAlice] !== -1) return memo[u][mask][isAlice];

        if (isAlice === 1) {
            let best = 0;
            for (let nxt = 0; nxt < p; nxt++) {
                if (!(mask & (1 << nxt))) {
                    const d = dist[u][nxt + 1];
                    const val = d + minimax(nxt + 1, mask | (1 << nxt), 0);
                    if (val > best) best = val;
                }
            }
            return memo[u][mask][isAlice] = best;
        } else {
            let best = 1e9;
            for (let nxt = 0; nxt < p; nxt++) {
                if (!(mask & (1 << nxt))) {
                    const d = dist[u][nxt + 1];
                    const val = d + minimax(nxt + 1, mask | (1 << nxt), 1);
                    if (val < best) best = val;
                }
            }
            return memo[u][mask][isAlice] = best;
        }
    }

    return minimax(0, 0, 1);
};
